/* ------------------------------------------------------------------------------
@name: Animation
@description: Animation
--------------------------------------------------------------------------------- */

const Animation = (() => {
  // handleScrolAnimate
  const handleAnimation = () => {
    // - handleRevealConfig
    const handleRevealConfig = (distance = "8px", delay = 250) => {
      const _config = {
        duration: 500,
        distance: distance,
        delay: delay,
        origin: "bottom",
        easing: "ease",
      };
      return _config;
    };

    // - handleRevealConfigInterval
    const handleRevealConfigInterval = (distance = "8px", delay = 200) => {
      const _config = {
        duration: 1000,
        distance: distance,
        delay: delay,
        origin: "bottom",
        easing: "ease",
        interval: 150,
      };
      return _config;
    };

    if ($(".hero").length) {
      ScrollReveal().reveal(".hero__ttl", handleRevealConfig());
    }

    if ($(".accordion").length) {
      ScrollReveal().reveal(".accordion__label", handleRevealConfigInterval());
      ScrollReveal().reveal(
        ".accordion__tab .btn",
        handleRevealConfigInterval(),
      );
      if ($(window).width() > 991.98) {
        ScrollReveal().reveal(".accordion__list", handleRevealConfigInterval());
      } else {
        ScrollReveal().reveal(".accordion__body", handleRevealConfigInterval());
      }
    }
  };

  // - init
  const init = () => {
    handleAnimation();
  };

  return {
    init,
  };
})();

export default Animation;
