import WindowResize from "@utilities/WindowResize.js";

const Category = (() => {
  const BREAKPOINT_DESKTOP = 991.98;

  // - isMobile
  const isMobile = () => $(window).width() <= BREAKPOINT_DESKTOP;

  // handleSetCategory
  const handleSetCategory = () => {
    $(".category .category__item").eq(0).addClass("category__item--active");
    $(".projects .projects__panel").eq(0).show();
  };

  // - handleClickDropdown
  const handleClickDropdown = () => {
    $(".category .category__dropdown__btn").on("click", (e) => {
      const _this = e.currentTarget;
      $(_this).toggleClass("active");
      $(".category__panel").slideToggle();
    });
  };

  const handleClickCategory = () => {
    $(".category__btn").on("click", (e) => {
      console.info("testtt aja");
      const _this = $(e.currentTarget);
      const $parents = _this.parents(".projects");
      const $item = _this.parents(".category__item");
      const $category = _this.closest(".category");
      const _target = $item.data("target");
      const _text = _this.text();

      $parents
        .find(`.projects__panel[data-index=${_target}]`)
        .show()
        .siblings(".projects__panel")
        .hide();

      if (!$item.hasClass("category__item--active")) {
        $item
          .addClass("category__item--active")
          .siblings(".category__item")
          .removeClass("category__item--active");
      }

      if (isMobile()) {
        $category
          .find(".category__dropdown__btn")
          .text(_text)
          .removeClass("active");
        $category.find(".category__panel").slideUp();
      }
    });
  };

  // - init
  const init = () => {
    handleSetCategory();
    handleClickCategory();
    handleClickDropdown();
    WindowResize.resize(isMobile);
  };

  return {
    init,
  };
})();

export default Category;
