/* ------------------------------------------------------------------------------
@name: Header
@description: Header
--------------------------------------------------------------------------------- */
import Scrolllable from "@utilities/Scrolllable";

const Header = (() => {
  // - handleClick
  const handleClick = () => {
    if ($(window).width() >= 991.98) {
      $(".header__menu").on("click", (e) => {
        if (e.target === e.currentTarget) {
          handleClose();
        }
      });
    }
  };

  // - handleEsc
  const handleEsc = () => {
    $(document).on("keyup", (e) => {
      if (e.which === 27) {
        handleClose();
      }
    });
  };

  // - handleClose
  const handleClose = () => {
    if ($("body").hasClass("show-menu")) {
      $("body").removeClass("show-menu");
      Scrolllable.enable();
    }
  };

  // - setVhUnit
  const setVhUnit = () => {
    var vh = $(window).height() * 0.01;
    $(":root").css("--vh", vh + "px");
  };

  const handleTheme = () => {
    const savedTheme = localStorage.getItem("current-theme");

    if (savedTheme === "dark") {
      $("body").removeClass("theme-light").addClass("theme-dark");
    } else {
      $("body").removeClass("theme-dark").addClass("theme-light");
    }

    $(".js-theme-dark").on("click", () => {
      if (!$("body").hasClass("theme-dark")) {
        $("body").removeClass("theme-light").addClass("theme-dark");

        localStorage.setItem("current-theme", "dark");
      }
    });

    $(".js-theme-light").on("click", () => {
      if (!$("body").hasClass("theme-light")) {
        $("body").removeClass("theme-dark").addClass("theme-light");

        localStorage.setItem("current-theme", "light");
      }
    });
  };

  // - init
  const init = () => {
    handleClick();
    handleEsc();
    setVhUnit();
    handleTheme();
  };

  return {
    init,
  };
})();

export default Header;
